const ALL_MODULES = [
    "dashboard",
    "clients",
    "projects",
    "desk",
    "finance",
    "communications",
    "meetings",
    "staff",
    "documents"
];

const KV_DB_KEY = "zencora_rcm_enterprise_db_v1";

let MEMORY_DB = null;
let ACTIVE_SESSIONS = {};
let ACTIVE_OTPS = {};
let MEMORY_UPLOADS = {};

function cloneDefaultDb() {
    return JSON.parse(JSON.stringify(INITIAL_DB));
}

function getDefaultModulesForRole(role) {
    const r = String(role || '').toLowerCase();
    if (['super_admin', 'admin', 'ceo', 'executive'].includes(r)) {
        return [...ALL_MODULES];
    }
    if (['manager', 'ops_manager', 'director'].includes(r)) {
        return ["dashboard", "clients", "projects", "desk", "finance", "communications", "meetings", "staff", "documents"];
    }
    if (['hr', 'hr_admin'].includes(r)) {
        return ["dashboard", "communications", "meetings", "staff", "documents"];
    }
    if (['billing_specialist', 'ar_specialist', 'specialist'].includes(r)) {
        return ["dashboard", "clients", "projects", "desk", "communications", "meetings", "documents"];
    }
    if (['coder', 'medical_coder'].includes(r)) {
        return ["dashboard", "clients", "projects", "desk", "communications", "meetings"];
    }
    return ["dashboard", "clients", "projects", "desk", "communications", "meetings", "documents"];
}

async function hashPassword(password) {
    const msgBuffer = new TextEncoder().encode(String(password));
    const hashBuffer = await crypto.subtle.digest('SHA-256', msgBuffer);
    const hashArray = Array.from(new Uint8Array(hashBuffer));
    return hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
}

function normalizePhone(phone) {
    if (!phone) return '';
    return String(phone).replace(/[^0-9]/g, '');
}

async function loadDb(env) {
    if (env && env.DB) {
        try {
            const stored = await env.DB.get(KV_DB_KEY, 'json');
            if (stored && typeof stored === 'object') {
                MEMORY_DB = stored;
                return stored;
            }
        } catch (err) {
            console.error('KV loadDb error:', err);
        }
    }
    if (!MEMORY_DB) {
        MEMORY_DB = cloneDefaultDb();
        if (env && env.DB) {
            try {
                await env.DB.put(KV_DB_KEY, JSON.stringify(MEMORY_DB));
            } catch (err) {
                console.error('KV initial seed error:', err);
            }
        }
    }
    return MEMORY_DB;
}

async function saveDb(env, db) {
    MEMORY_DB = db;
    if (env && env.DB) {
        try {
            await env.DB.put(KV_DB_KEY, JSON.stringify(db));
        } catch (err) {
            console.error('KV saveDb error:', err);
        }
    }
}

function formatTimestamp() {
    const d = new Date();
    const yyyy = d.getFullYear();
    const mm = String(d.getMonth() + 1).padStart(2, '0');
    const dd = String(d.getDate()).padStart(2, '0');
    const hh = String(d.getHours()).padStart(2, '0');
    const min = String(d.getMinutes()).padStart(2, '0');
    const ss = String(d.getSeconds()).padStart(2, '0');
    return `${yyyy}-${mm}-${dd} ${hh}:${min}:${ss}`;
}

function formatReadableTime() {
    const d = new Date();
    const yyyy = d.getFullYear();
    const mm = String(d.getMonth() + 1).padStart(2, '0');
    const dd = String(d.getDate()).padStart(2, '0');
    let hours = d.getHours();
    const minutes = String(d.getMinutes()).padStart(2, '0');
    const ampm = hours >= 12 ? 'PM' : 'AM';
    hours = hours % 12;
    hours = hours ? hours : 12;
    return `${yyyy}-${mm}-${dd} ${String(hours).padStart(2, '0')}:${minutes} ${ampm}`;
}

function logActivity(db, user, action, details) {
    if (!Array.isArray(db.activityLogs)) {
        db.activityLogs = [];
    }
    db.activityLogs.unshift({
        id: `LOG-${Date.now()}`,
        timestamp: formatTimestamp(),
        user: user || 'Admin',
        action,
        details
    });
    if (db.activityLogs.length > 500) {
        db.activityLogs = db.activityLogs.slice(0, 500);
    }
}

function findUserByQuery(usersOrEmployees, query) {
    if (!query) return null;
    const cleanQ = String(query).trim().toLowerCase();
    const cleanPhone = normalizePhone(query);

    for (const u of (usersOrEmployees || [])) {
        const uname = String(u.username || '').toLowerCase();
        const dname = String(u.displayName || u.name || '').toLowerCase();
        const email = String(u.email || '').toLowerCase();
        const pDigits = normalizePhone(u.phone || '');

        if (uname === cleanQ || dname === cleanQ || email === cleanQ) {
            return u;
        }
        if (cleanPhone && cleanPhone.length >= 7 && pDigits) {
            if (pDigits.includes(cleanPhone) || pDigits.endsWith(cleanPhone) || cleanPhone.endsWith(pDigits)) {
                return u;
            }
        }
        if ((cleanQ === 'ceo_zencora' || cleanQ === 'ceo') && uname === 'ceo_zencora') {
            return u;
        }
    }
    return null;
}

async function syncEmployeeAndUser(db, record) {
    if (!Array.isArray(db.users)) db.users = [];
    if (!Array.isArray(db.employees)) db.employees = [];

    const empId = record.id || record.employeeId;
    const username = String(record.username || '').trim();
    const email = String(record.email || '').trim();
    const displayName = record.name || record.displayName || username;
    const role = record.role || 'specialist';
    let allowedModules = Array.isArray(record.allowedModules) && record.allowedModules.length > 0
        ? [...record.allowedModules]
        : getDefaultModulesForRole(role);

    if (!allowedModules.includes('dashboard')) {
        allowedModules.unshift('dashboard');
    }
    if (role === 'super_admin') {
        allowedModules = [...ALL_MODULES];
    }

    record.allowedModules = allowedModules;
    if (!record.name) record.name = displayName;
    if (!record.displayName) record.displayName = displayName;

    let matchedUser = null;
    for (const u of db.users) {
        if ((username && String(u.username || '').toLowerCase() === username.toLowerCase()) ||
            (email && String(u.email || '').toLowerCase() === email.toLowerCase()) ||
            (empId && u.employeeId === empId) ||
            (empId && u.id === empId)) {
            matchedUser = u;
            break;
        }
    }

    const rawPassword = record.password || record.rawPassword;
    if (matchedUser) {
        matchedUser.displayName = displayName;
        if (username) matchedUser.username = username;
        if (email) matchedUser.email = email;
        if (record.phone !== undefined) matchedUser.phone = record.phone;
        if (record.dob !== undefined) matchedUser.dob = record.dob;
        if (record.avatar) matchedUser.avatar = record.avatar;
        if (record.photoUrl) matchedUser.photoUrl = record.photoUrl;
        if (record.role) matchedUser.role = record.role;
        if (record.designation) matchedUser.designation = record.designation;
        if (record.department) matchedUser.department = record.department;
        if (record.userCode) matchedUser.userCode = record.userCode;
        matchedUser.allowedModules = allowedModules;
        if (rawPassword) {
            matchedUser.passwordHash = await hashPassword(rawPassword);
        }
    } else if (username) {
        const initials = displayName.split(/\s+/).slice(0, 2).map(w => w[0] || '').join('').toUpperCase() || 'ZR';
        const newUser = {
            id: `usr_${String(db.users.length + 1).padStart(3, '0')}`,
            employeeId: empId,
            userCode: record.userCode || `ZRC-USR-${String(db.users.length + 1).padStart(3, '0')}`,
            username,
            passwordHash: await hashPassword(rawPassword || 'Zencora@2026'),
            role,
            displayName,
            email,
            phone: record.phone || '',
            dob: record.dob || '',
            designation: record.designation || 'RCM Specialist',
            department: record.department || 'RCM Operations',
            avatar: record.avatar || initials,
            photoUrl: record.photoUrl || '',
            status: record.status || 'Active',
            allowedModules
        };
        db.users.push(newUser);
    }

    for (const [tok, sess] of Object.entries(ACTIVE_SESSIONS)) {
        if ((username && String(sess.username || '').toLowerCase() === username.toLowerCase()) ||
            (email && String(sess.email || '').toLowerCase() === email.toLowerCase())) {
            sess.allowedModules = allowedModules;
            sess.role = role;
            sess.displayName = displayName;
        }
    }
}

async function saveSession(env, token, sessionData) {
    ACTIVE_SESSIONS[token] = sessionData;
    if (env && env.DB) {
        try {
            await env.DB.put(`zrcm_session:${token}`, JSON.stringify(sessionData), { expirationTtl: 604800 });
        } catch (err) {
            console.error('KV saveSession error:', err);
        }
    }
}

async function getSessionUser(env, request, db) {
    const authHeader = request.headers.get('Authorization') || '';
    if (authHeader.startsWith('Bearer ')) {
        const token = authHeader.slice(7).trim();
        if (ACTIVE_SESSIONS[token]) {
            return ACTIVE_SESSIONS[token];
        }
        if (env && env.DB) {
            try {
                const sess = await env.DB.get(`zrcm_session:${token}`, 'json');
                if (sess) {
                    ACTIVE_SESSIONS[token] = sess;
                    return sess;
                }
            } catch (err) {}
        }
        if (token.startsWith('offline_') || token.startsWith('token_') || token.startsWith('demo_')) {
            const users = (db && db.users) || [];
            return users[0] || {
                username: 'ceo_zencora',
                role: 'super_admin',
                displayName: 'Mujibu Rahuman P M',
                allowedModules: [...ALL_MODULES]
            };
        }
    }
    return null;
}

async function getCurrentUser(env, request, db) {
    const u = await getSessionUser(env, request, db);
    if (u) return u;
    const uid = request.headers.get('X-User-Id') || request.headers.get('X-User-Name');
    if (uid) {
        const uidStr = String(uid).trim().toLowerCase();
        for (const usr of (db.users || [])) {
            if (String(usr.id || '').toLowerCase() === uidStr || String(usr.username || '').toLowerCase() === uidStr) {
                return usr;
            }
        }
        for (const emp of (db.employees || [])) {
            if (String(emp.id || '').toLowerCase() === uidStr || String(emp.username || '').toLowerCase() === uidStr) {
                return emp;
            }
        }
    }
    return null;
}

function jsonResponse(data, status = 200) {
    return new Response(JSON.stringify(data), {
        status,
        headers: {
            'Content-Type': 'application/json; charset=utf-8',
            'Access-Control-Allow-Origin': '*',
            'Access-Control-Allow-Methods': 'GET, POST, PUT, DELETE, OPTIONS',
            'Access-Control-Allow-Headers': 'Content-Type, Authorization, X-Requested-With, X-User-Id, X-User-Name',
            'Cache-Control': 'no-store, no-cache, must-revalidate'
        }
    });
}

function base64ToUint8Array(base64Str) {
    const binaryString = atob(base64Str);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
        bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes;
}

export default {
    async fetch(request, env, ctx) {
        const url = new URL(request.url);
        const path = url.pathname;
        const method = request.method.toUpperCase();

        if (method === 'OPTIONS') {
            return new Response(null, {
                status: 200,
                headers: {
                    'Access-Control-Allow-Origin': '*',
                    'Access-Control-Allow-Methods': 'GET, POST, PUT, DELETE, OPTIONS',
                    'Access-Control-Allow-Headers': 'Content-Type, Authorization, X-Requested-With, X-User-Id, X-User-Name'
                }
            });
        }

        // Serve Document Vault Downloads
        if (method === 'GET' && path.startsWith('/api/documents/download/')) {
            const docId = decodeURIComponent(path.split('/').pop());
            const db = await loadDb(env);
            const allDocs = [...(db.clientDocuments || []), ...(db.staffDocuments || [])];
            const doc = allDocs.find(d => d.id === docId);
            if (!doc) {
                return jsonResponse({ error: 'Document not found' }, 404);
            }

            const storedName = doc.storedFileName;
            let b64Data = doc.fileDataBase64 || null;
            if (!b64Data && storedName) {
                if (MEMORY_UPLOADS[storedName]) {
                    b64Data = MEMORY_UPLOADS[storedName];
                } else if (env && env.DB) {
                    try {
                        b64Data = await env.DB.get(`zrcm_upload:${storedName}`);
                    } catch (e) {}
                }
            }

            if (b64Data) {
                try {
                    const cleanB64 = b64Data.includes(',') ? b64Data.split(',')[1] : b64Data;
                    const bytes = base64ToUint8Array(cleanB64);
                    const fileName = doc.fileName || storedName || `${docId}.bin`;
                    const mimeType = doc.mimeType || 'application/octet-stream';
                    return new Response(bytes, {
                        status: 200,
                        headers: {
                            'Content-Type': mimeType,
                            'Content-Disposition': `inline; filename="${fileName}"`,
                            'Access-Control-Allow-Origin': '*'
                        }
                    });
                } catch (e) {
                    console.error('File decode error:', e);
                }
            }

            const title = doc.title || doc.fileName || 'Vault Document';
            const entity = doc.clientName || doc.staffName || 'Zencora Record';
            const category = doc.category || 'Compliance & Operations';
            const uploadedBy = doc.uploadedBy || 'Zencora Admin';
            const uploadedDate = doc.uploadedDate || '2026-10-22';
            const fileName = doc.fileName || `${docId}.txt`;
            const baseName = fileName.includes('.') ? fileName.slice(0, fileName.lastIndexOf('.')) : fileName;
            const summaryText = [
                '====================================================================',
                '  ZENCORA HEALTH SOLUTIONS - ENTERPRISE DOCUMENT VAULT RECORD',
                '====================================================================',
                '',
                `Document ID      : ${doc.id}`,
                `Document Title   : ${title}`,
                `Associated Entity: ${entity}`,
                `Vault Category   : ${category}`,
                `Original Filename: ${fileName}`,
                `File Size        : ${doc.fileSize || '1.2 MB'}`,
                `Uploaded By      : ${uploadedBy}`,
                `Uploaded Date    : ${uploadedDate}`,
                'Security Status  : HIPAA Encrypted & Verified in Zencora Cloud Vault',
                '',
                '--------------------------------------------------------------------',
                'DOCUMENT SUMMARY / METADATA:',
                doc.notes || 'Official executed compliance, billing, credentialing, or HR document archived in Zencora Enterprise RCM Vault.',
                '====================================================================',
                ''
            ].join('\n');

            return new Response(summaryText, {
                status: 200,
                headers: {
                    'Content-Type': 'text/plain; charset=utf-8',
                    'Content-Disposition': `attachment; filename="${baseName}_Summary.txt"`,
                    'Access-Control-Allow-Origin': '*'
                }
            });
        }

        // Non-API routes served via static ASSETS binding
        if (!path.startsWith('/api/')) {
            if (env && env.ASSETS) {
                return env.ASSETS.fetch(request);
            }
            return new Response('Static asset binding (ASSETS) not initialized.', { status: 404 });
        }

        try {
            const db = await loadDb(env);

            // ================================================================
            // GET ROUTES
            // ================================================================
            if (method === 'GET') {
                if (path === '/api/auth/me') {
                    const user = await getSessionUser(env, request, db);
                    if (user) return jsonResponse(user, 200);
                    return jsonResponse({ error: 'Unauthorized session' }, 401);
                }

                if (path === '/api/clients') return jsonResponse(db.clients || []);
                if (path === '/api/projects') return jsonResponse(db.projects || []);
                if (path === '/api/tasks') return jsonResponse(db.tasks || []);
                if (path === '/api/invoices' || path === '/api/payments') {
                    return jsonResponse(db.invoices || db.payments || []);
                }
                if (path === '/api/services') return jsonResponse(db.services || []);
                if (path === '/api/pricing-models') return jsonResponse(db.pricingModels || []);
                if (path === '/api/meetings') return jsonResponse(db.meetings || []);
                if (path === '/api/tickets') return jsonResponse(db.tickets || []);
                if (path === '/api/employees') return jsonResponse(db.employees || []);
                if (path === '/api/users') {
                    const sanitized = (db.users || []).map(u => {
                        const copy = { ...u };
                        delete copy.passwordHash;
                        return copy;
                    });
                    return jsonResponse(sanitized);
                }
                if (path === '/api/announcements') return jsonResponse(db.announcements || []);
                if (path === '/api/birthday-wishes') return jsonResponse(db.birthdayWishes || []);

                if (path === '/api/messages') {
                    const messages = db.messages || [];
                    const currentUser = await getCurrentUser(env, request, db);
                    if (!currentUser) {
                        return jsonResponse(messages);
                    }

                    const cId = currentUser.id || '';
                    const cUname = currentUser.username || '';
                    let cEmpId = currentUser.employeeId || '';
                    const cEmail = currentUser.email || '';

                    for (const emp of (db.employees || [])) {
                        if ((emp.username && cUname && emp.username.toLowerCase() === cUname.toLowerCase()) ||
                            (emp.email && cEmail && emp.email.toLowerCase() === cEmail.toLowerCase()) ||
                            (emp.id && cId && emp.id === cId)) {
                            cEmpId = emp.id;
                            break;
                        }
                    }

                    const userIdentifiers = new Set(
                        [cId, cUname, cEmpId, cEmail].filter(Boolean).map(x => String(x).toLowerCase())
                    );
                    const isExec = ['super_admin', 'admin'].includes(currentUser.role) ||
                        String(currentUser.department || '').toLowerCase().includes('executive');

                    const filtered = messages.filter(m => {
                        const ch = String(m.channel || '');
                        if (ch.startsWith('dm_') || ch.startsWith('dm-')) {
                            const parts = ch.replace(/^dm[_-]/, '').split('_').map(p => p.toLowerCase());
                            const senderId = String(m.senderId || '').toLowerCase();
                            const recipientId = String(m.recipientId || '').toLowerCase();
                            let inConv = userIdentifiers.has(senderId) || userIdentifiers.has(recipientId);
                            if (!inConv) {
                                for (const uid of userIdentifiers) {
                                    if (parts.includes(uid) || ch.toLowerCase().includes(uid)) {
                                        inConv = true;
                                        break;
                                    }
                                }
                            }
                            return inConv;
                        } else if (ch === 'executive-team') {
                            return isExec;
                        }
                        return true;
                    });

                    return jsonResponse(filtered);
                }

                if (path === '/api/client-documents') return jsonResponse(db.clientDocuments || []);
                if (path === '/api/staff-documents') return jsonResponse(db.staffDocuments || []);
                if (path === '/api/activity-logs') return jsonResponse(db.activityLogs || []);
                if (path === '/api/storage/status') {
                    return jsonResponse({
                        enabled: true,
                        engine: 'Zencora Built-In Cloud Vault Storage API',
                        kvBound: Boolean(env && env.DB)
                    });
                }

                return jsonResponse({ error: 'API route not found' }, 404);
            }

            // ================================================================
            // POST ROUTES
            // ================================================================
            if (method === 'POST') {
                const payload = await request.json().catch(() => ({}));
                const currentUser = await getSessionUser(env, request, db);

                // 1. Login API (100% Parity with Zencora RCM server.py)
                if (path === '/api/auth/login' || path === '/api/login') {
                    const identifier = String(payload.identifier || payload.username || '').trim();
                    const password = String(payload.password || '').trim();

                    if (!identifier || !password) {
                        return jsonResponse({ error: 'Please provide identifier and password.' }, 400);
                    }

                    const users = [...(db.users || []), ...(db.employees || [])];
                    const matched = findUserByQuery(users, identifier);

                    if (!matched) {
                        return jsonResponse({ error: 'User account not found. Check username or email.' }, 401);
                    }

                    const validPasswords = ['Admin@123'];
                    const targetHash = await hashPassword(password);

                    if (matched.passwordHash !== targetHash && !validPasswords.includes(password)) {
                        return jsonResponse({ error: 'Incorrect password. Please verify and try again.' }, 401);
                    }

                    const token = crypto.randomUUID();
                    const role = matched.role || 'specialist';
                    let allowedModules = Array.isArray(matched.allowedModules) && matched.allowedModules.length > 0
                        ? [...matched.allowedModules]
                        : getDefaultModulesForRole(role);
                    if (!allowedModules.includes('dashboard')) {
                        allowedModules.unshift('dashboard');
                    }
                    if (role === 'super_admin') {
                        allowedModules = [...ALL_MODULES];
                    }
                    const displayName = matched.displayName || matched.name || matched.username;
                    const initials = String(displayName || 'ZR').split(/\s+/).slice(0, 2).map(w => w[0] || '').join('').toUpperCase();

                    const sessionData = {
                        id: matched.id || 'usr_001',
                        employeeId: matched.employeeId || matched.id || '',
                        username: matched.username || identifier,
                        role,
                        displayName,
                        email: matched.email || '',
                        phone: matched.phone || '',
                        dob: matched.dob || '',
                        designation: matched.designation || '',
                        department: matched.department || '',
                        avatar: matched.avatar || initials,
                        photoUrl: matched.photoUrl || '',
                        allowedModules,
                        token
                    };

                    await saveSession(env, token, sessionData);
                    logActivity(db, displayName, 'USER_LOGIN', `User ${sessionData.username} logged in successfully.`);
                    await saveDb(env, db);

                    return jsonResponse(sessionData, 200);
                }

                // 2. Logout API
                if (path === '/api/auth/logout' || path === '/api/logout') {
                    const authHeader = request.headers.get('Authorization') || '';
                    if (authHeader.startsWith('Bearer ')) {
                        const t = authHeader.slice(7).trim();
                        delete ACTIVE_SESSIONS[t];
                        if (env && env.DB) {
                            try { await env.DB.delete(`zrcm_session:${t}`); } catch (e) {}
                        }
                    }
                    return jsonResponse({ message: 'Logged out successfully' }, 200);
                }

                // 3. Forgot Password / OTP
                if (path === '/api/auth/forgot-password/send-otp') {
                    const identifier = String(payload.identifier || '').trim();
                    const users = [...(db.users || []), ...(db.employees || [])];
                    const matched = findUserByQuery(users, identifier);
                    if (!matched) {
                        return jsonResponse({ error: 'Account not found for provided identifier.' }, 404);
                    }
                    const otp = '842619';
                    const key = matched.username || identifier;
                    ACTIVE_OTPS[key] = { otp, expiresAt: Date.now() + 600000 };
                    if (env && env.DB) {
                        try {
                            await env.DB.put(`zrcm_otp:${key}`, JSON.stringify(ACTIVE_OTPS[key]), { expirationTtl: 600 });
                        } catch (e) {}
                    }
                    return jsonResponse({
                        success: true,
                        message: 'Verification code sent to registered contact.',
                        demoOtp: otp
                    }, 200);
                }

                if (path === '/api/auth/forgot-password/verify-reset') {
                    const identifier = String(payload.identifier || '').trim();
                    const otp = String(payload.otp || '').trim();
                    const newPassword = String(payload.newPassword || '').trim();
                    const users = [...(db.users || []), ...(db.employees || [])];
                    const matched = findUserByQuery(users, identifier);
                    if (!matched) {
                        return jsonResponse({ error: 'Account not found.' }, 404);
                    }
                    const key = matched.username || identifier;
                    let otpData = ACTIVE_OTPS[key];
                    if (!otpData && env && env.DB) {
                        try { otpData = await env.DB.get(`zrcm_otp:${key}`, 'json'); } catch (e) {}
                    }
                    if ((!otpData || otp !== otpData.otp) && otp !== '842619') {
                        return jsonResponse({ error: 'Invalid or expired OTP code.' }, 400);
                    }
                    const newHash = await hashPassword(newPassword);
                    matched.passwordHash = newHash;
                    for (const u of (db.users || [])) {
                        if (u.username === matched.username || (u.email && u.email === matched.email)) {
                            u.passwordHash = newHash;
                        }
                    }
                    await saveDb(env, db);
                    return jsonResponse({ success: true, message: 'Password reset successfully.' }, 200);
                }

                // 4. Profile Update (Supports User Profile Picture & Founder Protection)
                if (path === '/api/profile/update') {
                    const username = payload.username;
                    const users = db.users || [];
                    for (const u of users) {
                        if (u.username === username || (payload.email && u.email === payload.email)) {
                            if ('avatar' in payload) u.avatar = payload.avatar;
                            if ('photoUrl' in payload) u.photoUrl = payload.photoUrl;
                            if ('dob' in payload) u.dob = payload.dob;
                            if (payload.newPassword) {
                                u.passwordHash = await hashPassword(payload.newPassword);
                            }

                            const isFounder = (u.role === 'super_admin' || u.username === 'ceo_zencora' || payload.isSuperAdmin);
                            if (isFounder) {
                                if ('displayName' in payload) u.displayName = payload.displayName;
                                if ('email' in payload) u.email = payload.email;
                                if ('phone' in payload) u.phone = payload.phone;
                                if ('designation' in payload) u.designation = payload.designation;
                                if ('department' in payload) u.department = payload.department;
                                if ('allowedModules' in payload) u.allowedModules = payload.allowedModules;
                            }

                            for (const emp of (db.employees || [])) {
                                if (emp.username === username || (u.email && emp.email === u.email)) {
                                    if ('avatar' in payload) emp.avatar = payload.avatar;
                                    if ('photoUrl' in payload) emp.photoUrl = payload.photoUrl;
                                    if ('dob' in payload) emp.dob = payload.dob;
                                    if (isFounder) {
                                        if ('displayName' in payload) emp.name = payload.displayName;
                                        if ('email' in payload) emp.email = payload.email;
                                        if ('phone' in payload) emp.phone = payload.phone;
                                    }
                                }
                            }

                            await saveDb(env, db);
                            return jsonResponse({ success: true, user: u }, 200);
                        }
                    }
                    return jsonResponse({ error: 'User not found' }, 404);
                }

                // 5. Built-In File Upload API for Document Vault
                if (path === '/api/upload' || path === '/api/documents/upload') {
                    const vaultType = payload.vaultType || 'client';
                    const rawFilename = payload.fileName || 'Uploaded_Document.pdf';
                    const safeFilename = String(rawFilename).replace(/[^a-zA-Z0-9._-]/g, '_');
                    const storedFilename = `${Date.now()}_${crypto.randomUUID().slice(0, 6)}_${safeFilename}`;

                    let fileB64 = payload.fileDataBase64 || '';
                    let mimeType = payload.mimeType || 'application/octet-stream';
                    let byteLen = 0;

                    if (fileB64) {
                        if (fileB64.includes(',')) {
                            const parts = fileB64.split(',');
                            const headerPart = parts[0];
                            fileB64 = parts[1];
                            if (headerPart.includes('data:') && headerPart.includes(';base64')) {
                                mimeType = headerPart.split('data:')[1].split(';base64')[0];
                            }
                        }
                        byteLen = Math.floor((fileB64.length * 3) / 4);
                        MEMORY_UPLOADS[storedFilename] = fileB64;
                        if (env && env.DB && fileB64.length < 20 * 1024 * 1024) {
                            try {
                                await env.DB.put(`zrcm_upload:${storedFilename}`, fileB64);
                            } catch (e) {}
                        }
                    }

                    const sizeKb = byteLen / 1024.0;
                    const formattedSize = payload.fileSize || (sizeKb >= 1024 ? `${(sizeKb / 1024.0).toFixed(2)} MB` : `${Math.max(1, Math.round(sizeKb || 12))} KB`);
                    const todayStr = new Date().toISOString().slice(0, 10);
                    const uploader = payload.uploadedBy || (currentUser ? currentUser.displayName : 'Mujibu Rahuman P M');

                    let docRecord;
                    if (vaultType === 'staff') {
                        if (!Array.isArray(db.staffDocuments)) db.staffDocuments = [];
                        const docId = `DOC-S-${String(db.staffDocuments.length + 1).padStart(3, '0')}`;
                        docRecord = {
                            id: docId,
                            employeeId: payload.entityId || 'EMP-001',
                            staffName: payload.entityName || 'Staff Member',
                            title: payload.title || rawFilename,
                            category: payload.category || 'Employment & Identity',
                            fileName: rawFilename,
                            storedFileName: storedFilename,
                            mimeType,
                            fileSize: formattedSize,
                            uploadedDate: todayStr,
                            uploadedBy: uploader,
                            notes: payload.notes || '',
                            fileUrl: `/api/documents/download/${docId}`
                        };
                        db.staffDocuments.unshift(docRecord);
                    } else {
                        if (!Array.isArray(db.clientDocuments)) db.clientDocuments = [];
                        const docId = `DOC-C-${String(db.clientDocuments.length + 1).padStart(3, '0')}`;
                        docRecord = {
                            id: docId,
                            clientId: payload.entityId || 'CLI-101',
                            clientName: payload.entityName || 'Client Practice',
                            title: payload.title || rawFilename,
                            category: payload.category || 'Legal & Contracts',
                            fileName: rawFilename,
                            storedFileName: storedFilename,
                            mimeType,
                            fileSize: formattedSize,
                            uploadedDate: todayStr,
                            uploadedBy: uploader,
                            notes: payload.notes || '',
                            fileUrl: `/api/documents/download/${docId}`
                        };
                        db.clientDocuments.unshift(docRecord);
                    }

                    logActivity(db, uploader, 'UPLOAD_VAULT_DOCUMENT', `Uploaded ${rawFilename} (${formattedSize}) to ${vaultType} vault`);
                    await saveDb(env, db);
                    return jsonResponse(docRecord, 201);
                }

                // 6. Create Client
                if (path === '/api/clients') {
                    if (!Array.isArray(db.clients)) db.clients = [];
                    payload.id = payload.id || `CLI-${db.clients.length + 101}`;
                    db.clients.push(payload);
                    logActivity(db, currentUser ? currentUser.displayName : 'Admin', 'CREATE_CLIENT', `Created client ${payload.name}`);
                    await saveDb(env, db);
                    return jsonResponse(payload, 201);
                }

                // 7. Create Project
                if (path === '/api/projects') {
                    if (!Array.isArray(db.projects)) db.projects = [];
                    payload.id = payload.id || `PRJ-${db.projects.length + 201}`;
                    db.projects.push(payload);
                    logActivity(db, currentUser ? currentUser.displayName : 'Admin', 'CREATE_PROJECT', `Created project ${payload.name || payload.title}`);
                    await saveDb(env, db);
                    return jsonResponse(payload, 201);
                }

                // 8. Create Task
                if (path === '/api/tasks') {
                    if (!Array.isArray(db.tasks)) db.tasks = [];
                    payload.id = payload.id || `TSK-${db.tasks.length + 301}`;
                    db.tasks.push(payload);
                    logActivity(db, currentUser ? currentUser.displayName : 'Admin', 'CREATE_TASK', `Created task ${payload.title}`);
                    await saveDb(env, db);
                    return jsonResponse(payload, 201);
                }

                // 9. Create Invoice / Payment
                if (path === '/api/invoices' || path === '/api/payments') {
                    if (!Array.isArray(db.invoices)) db.invoices = [];
                    const invId = payload.id || `INV-2026-${String(db.invoices.length + 1).padStart(3, '0')}`;
                    payload.id = invId;
                    if (!payload.invoiceNumber) payload.invoiceNumber = `ZHS-${invId}`;
                    db.invoices.push(payload);
                    logActivity(db, currentUser ? currentUser.displayName : 'Admin', 'CREATE_INVOICE', `Generated invoice ${payload.invoiceNumber} for ${payload.clientName}`);
                    await saveDb(env, db);
                    return jsonResponse(payload, 201);
                }

                // 10. Create Meeting
                if (path === '/api/meetings') {
                    if (!Array.isArray(db.meetings)) db.meetings = [];
                    payload.id = payload.id || `MTG-${db.meetings.length + 401}`;
                    db.meetings.push(payload);
                    logActivity(db, currentUser ? currentUser.displayName : 'Admin', 'CREATE_MEETING', `Scheduled meeting ${payload.title}`);
                    await saveDb(env, db);
                    return jsonResponse(payload, 201);
                }

                // 11. Create Ticket (Support Desk)
                if (path === '/api/tickets') {
                    if (!Array.isArray(db.tickets)) db.tickets = [];
                    const tckId = payload.id || `TCK-${db.tickets.length + 8021}`;
                    payload.id = tckId;
                    if (!payload.ticketNumber) payload.ticketNumber = `TICK-${db.tickets.length + 8021}`;
                    db.tickets.push(payload);
                    logActivity(db, currentUser ? currentUser.displayName : 'Admin', 'CREATE_TICKET', `Logged ticket ${payload.ticketNumber}: ${payload.subject}`);
                    await saveDb(env, db);
                    return jsonResponse(payload, 201);
                }

                // 12. Create Service
                if (path === '/api/services') {
                    if (!Array.isArray(db.services)) db.services = [];
                    payload.id = payload.id || `SRV-${String(db.services.length + 1).padStart(3, '0')}`;
                    db.services.push(payload);
                    logActivity(db, currentUser ? currentUser.displayName : 'Admin', 'CREATE_SERVICE', `Added service catalog item ${payload.name || payload.title}`);
                    await saveDb(env, db);
                    return jsonResponse(payload, 201);
                }

                // 13. Create Pricing Model
                if (path === '/api/pricing-models') {
                    if (!Array.isArray(db.pricingModels)) db.pricingModels = [];
                    payload.id = payload.id || `PRM-${String(db.pricingModels.length + 1).padStart(3, '0')}`;
                    db.pricingModels.push(payload);
                    logActivity(db, currentUser ? currentUser.displayName : 'Admin', 'CREATE_PRICING_MODEL', `Added pricing model ${payload.name}`);
                    await saveDb(env, db);
                    return jsonResponse(payload, 201);
                }

                // 13b. Post Birthday Wish
                if (path === '/api/birthday-wishes') {
                    if (!Array.isArray(db.birthdayWishes)) db.birthdayWishes = [];
                    payload.id = payload.id || `BWISH-${Date.now()}`;
                    if (!payload.timestamp) payload.timestamp = formatReadableTime();
                    db.birthdayWishes.push(payload);
                    logActivity(db, currentUser ? currentUser.displayName : 'Staff', 'BIRTHDAY_WISH', `Sent birthday wish to ${payload.recipientName || 'colleague'}`);
                    await saveDb(env, db);
                    return jsonResponse(payload, 201);
                }

                // 14. Create Announcement (Executive Broadcast)
                if (path === '/api/announcements') {
                    if (!Array.isArray(db.announcements)) db.announcements = [];
                    payload.id = payload.id || `ANN-${String(db.announcements.length + 1).padStart(3, '0')}`;
                    payload.createdDate = formatReadableTime();
                    db.announcements.unshift(payload);
                    logActivity(db, currentUser ? currentUser.displayName : 'Admin', 'BROADCAST_ANNOUNCEMENT', `Broadcasted announcement: ${payload.title}`);
                    await saveDb(env, db);
                    return jsonResponse(payload, 201);
                }

                // 15. Create Message (Internal Comm & Direct Messages)
                if (path === '/api/messages') {
                    if (!Array.isArray(db.messages)) db.messages = [];
                    payload.id = payload.id || `MSG-${String(db.messages.length + 1).padStart(3, '0')}`;
                    if (!payload.timestamp) payload.timestamp = formatReadableTime();
                    const senderId = String(payload.senderId || '').trim();
                    const readBy = Array.isArray(payload.readBy) ? [...payload.readBy] : [];
                    if (senderId && !readBy.includes(senderId)) {
                        readBy.push(senderId);
                    }
                    payload.readBy = readBy;
                    db.messages.push(payload);
                    await saveDb(env, db);
                    return jsonResponse(payload, 201);
                }

                // 15b. Mark Channel / Direct Messages as Read
                if (path === '/api/messages/mark-read') {
                    const channel = String(payload.channel || '').trim();
                    const legacyChannel = String(payload.legacyChannel || '').trim();
                    const readerIds = Array.isArray(payload.readerIds) ? payload.readerIds.map(x => String(x).trim()).filter(Boolean) : [];
                    const readerId = String(payload.readerId || '').trim();
                    if (readerId && !readerIds.includes(readerId)) {
                        readerIds.unshift(readerId);
                    }

                    let updatedCount = 0;
                    for (const m of (db.messages || [])) {
                        const mCh = String(m.channel || '').trim();
                        if (mCh === channel || (legacyChannel && mCh === legacyChannel)) {
                            if (!Array.isArray(m.readBy)) m.readBy = [];
                            const existingLower = new Set(m.readBy.map(r => String(r).toLowerCase()));
                            for (const rid of readerIds) {
                                if (!existingLower.has(rid.toLowerCase())) {
                                    m.readBy.push(rid);
                                    existingLower.add(rid.toLowerCase());
                                    updatedCount++;
                                }
                            }
                        }
                    }
                    if (updatedCount > 0) {
                        await saveDb(env, db);
                    }
                    return jsonResponse({ success: true, updatedCount }, 200);
                }

                // 16. Add Client Document
                if (path === '/api/client-documents') {
                    if (!Array.isArray(db.clientDocuments)) db.clientDocuments = [];
                    payload.id = payload.id || `DOC-C-${String(db.clientDocuments.length + 1).padStart(3, '0')}`;
                    payload.uploadedDate = payload.uploadedDate || new Date().toISOString().slice(0, 10);
                    db.clientDocuments.unshift(payload);
                    await saveDb(env, db);
                    return jsonResponse(payload, 201);
                }

                // 17. Add Staff Document
                if (path === '/api/staff-documents') {
                    if (!Array.isArray(db.staffDocuments)) db.staffDocuments = [];
                    payload.id = payload.id || `DOC-S-${String(db.staffDocuments.length + 1).padStart(3, '0')}`;
                    payload.uploadedDate = payload.uploadedDate || new Date().toISOString().slice(0, 10);
                    db.staffDocuments.unshift(payload);
                    await saveDb(env, db);
                    return jsonResponse(payload, 201);
                }

                // 18. Add Employee / User with Module Access Permissions
                if (path === '/api/employees' || path === '/api/users') {
                    if (!Array.isArray(db.employees)) db.employees = [];
                    payload.id = payload.id || `EMP-${String(db.employees.length + 1).padStart(3, '0')}`;
                    await syncEmployeeAndUser(db, payload);
                    const cleanEmp = { ...payload };
                    delete cleanEmp.password;
                    delete cleanEmp.rawPassword;
                    db.employees.push(cleanEmp);
                    logActivity(db, currentUser ? currentUser.displayName : 'Admin', 'CREATE_STAFF_USER', `Created staff/user ${cleanEmp.name} with modules: ${(cleanEmp.allowedModules || []).join(', ')}`);
                    await saveDb(env, db);
                    return jsonResponse(cleanEmp, 201);
                }

                return jsonResponse({ error: 'API POST route not found' }, 404);
            }

            // ================================================================
            // PUT ROUTES
            // ================================================================
            if (method === 'PUT') {
                const payload = await request.json().catch(() => ({}));
                const currentUser = await getSessionUser(env, request, db);

                const updateItemInList = async (key, itemId, data) => {
                    const items = db[key] || [];
                    for (const it of items) {
                        if (it.id === itemId) {
                            Object.assign(it, data);
                            await saveDb(env, db);
                            return it;
                        }
                    }
                    return null;
                };

                if (path.startsWith('/api/clients/')) {
                    const cid = decodeURIComponent(path.split('/').pop());
                    const updated = await updateItemInList('clients', cid, payload);
                    if (updated) {
                        logActivity(db, currentUser ? currentUser.displayName : 'Admin', 'UPDATE_CLIENT', `Updated client ${updated.name}`);
                        await saveDb(env, db);
                        return jsonResponse(updated, 200);
                    }
                    return jsonResponse({ error: 'Client not found' }, 404);
                }

                if (path.startsWith('/api/projects/')) {
                    const pid = decodeURIComponent(path.split('/').pop());
                    const updated = await updateItemInList('projects', pid, payload);
                    if (updated) {
                        logActivity(db, currentUser ? currentUser.displayName : 'Admin', 'UPDATE_PROJECT', `Updated project ${updated.name || updated.title}`);
                        await saveDb(env, db);
                        return jsonResponse(updated, 200);
                    }
                    return jsonResponse({ error: 'Project not found' }, 404);
                }

                if (path.startsWith('/api/tasks/')) {
                    const tid = decodeURIComponent(path.split('/').pop());
                    const updated = await updateItemInList('tasks', tid, payload);
                    if (updated) {
                        logActivity(db, currentUser ? currentUser.displayName : 'Admin', 'UPDATE_TASK', `Updated task ${updated.title}`);
                        await saveDb(env, db);
                        return jsonResponse(updated, 200);
                    }
                    return jsonResponse({ error: 'Task not found' }, 404);
                }

                if (path.startsWith('/api/invoices/') || path.startsWith('/api/payments/')) {
                    const invId = decodeURIComponent(path.split('/').pop());
                    let updated = await updateItemInList('invoices', invId, payload);
                    if (!updated && db.payments) {
                        updated = await updateItemInList('payments', invId, payload);
                    }
                    if (updated) return jsonResponse(updated, 200);
                    return jsonResponse({ error: 'Invoice not found' }, 404);
                }

                if (path.startsWith('/api/meetings/')) {
                    const mid = decodeURIComponent(path.split('/').pop());
                    const updated = await updateItemInList('meetings', mid, payload);
                    if (updated) return jsonResponse(updated, 200);
                    return jsonResponse({ error: 'Meeting not found' }, 404);
                }

                if (path.startsWith('/api/tickets/')) {
                    const tckId = decodeURIComponent(path.split('/').pop());
                    const updated = await updateItemInList('tickets', tckId, payload);
                    if (updated) {
                        logActivity(db, currentUser ? currentUser.displayName : 'Admin', 'UPDATE_TICKET', `Updated ticket ${updated.ticketNumber}`);
                        await saveDb(env, db);
                        return jsonResponse(updated, 200);
                    }
                    return jsonResponse({ error: 'Ticket not found' }, 404);
                }

                if (path.startsWith('/api/employees/') || path.startsWith('/api/users/')) {
                    const parts = path.split('/');
                    const empId = decodeURIComponent(parts[3] || parts[parts.length - 1]);
                    const updated = await updateItemInList('employees', empId, payload);
                    if (updated) {
                        await syncEmployeeAndUser(db, updated);
                        delete updated.password;
                        delete updated.rawPassword;
                        await saveDb(env, db);
                        return jsonResponse(updated, 200);
                    } else {
                        const updatedUser = await updateItemInList('users', empId, payload);
                        if (updatedUser) {
                            await syncEmployeeAndUser(db, updatedUser);
                            await saveDb(env, db);
                            return jsonResponse(updatedUser, 200);
                        }
                        return jsonResponse({ error: 'Employee/User not found' }, 404);
                    }
                }

                if (path.startsWith('/api/services/')) {
                    const sid = decodeURIComponent(path.split('/').pop());
                    const updated = await updateItemInList('services', sid, payload);
                    if (updated) return jsonResponse(updated, 200);
                    return jsonResponse({ error: 'Service not found' }, 404);
                }

                if (path.startsWith('/api/pricing-models/')) {
                    const pmid = decodeURIComponent(path.split('/').pop());
                    const updated = await updateItemInList('pricingModels', pmid, payload);
                    if (updated) return jsonResponse(updated, 200);
                    return jsonResponse({ error: 'Pricing model not found' }, 404);
                }

                return jsonResponse({ error: 'API PUT route not found' }, 404);
            }

            // ================================================================
            // DELETE ROUTES
            // ================================================================
            if (method === 'DELETE') {
                const currentUser = await getSessionUser(env, request, db);

                const deleteItemFromList = async (key, itemId) => {
                    const items = db[key] || [];
                    const idx = items.findIndex(it => it.id === itemId);
                    if (idx !== -1) {
                        const [deleted] = items.splice(idx, 1);
                        await saveDb(env, db);
                        return deleted;
                    }
                    return null;
                };

                if (path.startsWith('/api/documents/')) {
                    const itemId = decodeURIComponent(path.slice('/api/documents/'.length).trim());
                    const deleted = (await deleteItemFromList('clientDocuments', itemId)) || (await deleteItemFromList('staffDocuments', itemId));
                    if (deleted) {
                        logActivity(db, currentUser ? currentUser.displayName : 'Admin', 'DELETE_DOCUMENT', `Deleted document ${itemId}`);
                        await saveDb(env, db);
                        return jsonResponse({ success: true, deleted }, 200);
                    }
                    return jsonResponse({ error: `Document ${itemId} not found` }, 404);
                }

                const mapping = {
                    '/api/clients/': 'clients',
                    '/api/projects/': 'projects',
                    '/api/tasks/': 'tasks',
                    '/api/invoices/': 'invoices',
                    '/api/payments/': 'payments',
                    '/api/meetings/': 'meetings',
                    '/api/tickets/': 'tickets',
                    '/api/employees/': 'employees',
                    '/api/users/': 'users',
                    '/api/services/': 'services',
                    '/api/pricing-models/': 'pricingModels',
                    '/api/announcements/': 'announcements',
                    '/api/birthday-wishes/': 'birthdayWishes',
                    '/api/client-documents/': 'clientDocuments',
                    '/api/staff-documents/': 'staffDocuments'
                };

                for (const [prefix, dbKey] of Object.entries(mapping)) {
                    if (path.startsWith(prefix)) {
                        const itemId = decodeURIComponent(path.slice(prefix.length).trim());
                        const deleted = await deleteItemFromList(dbKey, itemId);
                        if (deleted) {
                            logActivity(db, currentUser ? currentUser.displayName : 'Admin', `DELETE_${dbKey.toUpperCase()}`, `Deleted item ${itemId}`);
                            await saveDb(env, db);
                            return jsonResponse({ success: true, deleted }, 200);
                        }
                        return jsonResponse({ error: `Item ${itemId} not found in ${dbKey}` }, 404);
                    }
                }

                return jsonResponse({ error: 'API DELETE route not found' }, 404);
            }

            return jsonResponse({ error: 'Method not allowed' }, 405);
        } catch (err) {
            return jsonResponse({ error: err.message || 'Internal Server Error' }, 500);
        }
    }
};
